    intro: "Ptah Tours فريق مقرّه القاهرة من علماء المصريات والمرشدين ومصمّمي الرحلات. نبني رحلات خاصة ولمجموعات صغيرة عبر مصر — من أهرامات الجيزة إلى معابد الجنوب وسكينة النيل — لمسافرين يريدون أكثر من محطة لالتقاط صورة.",
    storyHeading: "قصّتنا",
    storyParagraphs: [
      "بدأت Ptah Tours من إحباط بسيط: أناس كثيرون جدًّا كانوا يغادرون مصر وقد رأوا الآثار لكنهم لم يفهموها حقًّا. حافلات مستعجلة، وزيارات مزدحمة عند الظهيرة، ومرشدون يقرؤون من بطاقة مغلّفة — كان البلد يستحقّ أفضل من ذلك، وكذلك من قطعوا كل تلك المسافة لرؤيته.",
      "فبنينا الشركة التي تمنّينا وجودها. وقد سُمّيت تيمّنًا بـPtah، إله الحِرَفيين والصُّنّاع في مِنف، فنعامل كل برنامج بوصفه شيئًا يُصاغ بإتقان — مرتَّبًا حول الضوء والزحام، يقوده من أمضوا حياتهم مع هذه المواقع، وبإيقاعٍ يترك متّسعًا لاستيعابه فعلًا.",
      "اليوم نرحّب بمسافرين من جميع أنحاء العالم، لكن قلب الشركة لم يبرح مكانه: لا يزال فريقًا في القاهرة يحبّ هذا المكان ويريدك أن تحبّه أيضًا.",
    ],
    promisesHeading: "ما نَعِد به",
    promises: [
      { title: "مرشدون مرخَّصون في علم المصريات", body: "تقود كل جولة عالِم مصريات مرخَّص — لا نصّ محفوظ. يقرؤون الجدران، ويجيبون عن الأسئلة الصعبة، ويوقّتون كل موقع لتراه في أبهى حالاته، لا في أكثرها ازدحامًا." },
      { title: "تسعير صادق وشامل", body: "السعر الذي تراه هو السعر الذي تدفعه. رسوم الدخول وخدمات النقل والتفاصيل مبيّنة قبل أن تحجز — لا بنود مفاجئة عند بوابة المعبد." },
      { title: "مجموعات صغيرة، وخاصة بالأصل", body: "نحدّد سقفًا لأحجام المجموعات ونجعل الانطلاقات الخاصة هي الأصل لينحني الإيقاع لك. صباحات متأنّية في الجيزة، وساعة إضافية في وادي الملوك — اليوم يومك." },
      { title: "محليّون، على مدار السنة", body: "نحن نعيش هنا. وحين تتبدّل الخطط — إضراب، أو موجة حرّ، أو مقبرة مغلقة — يردّ رقم هاتف في القاهرة، ويتولّى الأمرَ من يعرف أرض الواقع." },
    ],
    valuesHeading: "كيف نسافر",
    values: [
      { title: "احترام الأماكن التي نزورها", body: "تراث مصر يبقى بعدنا جميعًا. نسافر بطرق تحمي المواقع وتدعم المجتمعات التي ترعاها." },
      { title: "العمق قبل قوائم المهام", body: "نفضّل أن تفهم معبدًا واحدًا على أن تصوّر عشرة. تترك برامجنا متّسعًا للتمهّل والسؤال وتذكّر اليوم فعلًا." },
      { title: "عناية بالتفاصيل", body: "المرشد المناسب، والجانب المظلّل من الحافلة، والماء حين تحتاجه. السفر الجيد ألف قرار صغير يُتَّخذ نيابةً عنك." },
    ],
    teamHeading: "علماء المصريات لدينا",
    teamIntro: "تقود كل رحلة من Ptah عالِم مصريات مرخَّص — مرشد محترف مدرَّب على تاريخ مصر وآثارها، ومرخَّص من وزارة السياحة والآثار. هم السبب في أن تتحوّل الزيارة إلى فهم.",
